/root/.claude-cfg/.wsp-config-tmp.abababababab
{
  "numStartups": 3,
  "mcpServers": {
    "github": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@modelcontextprotocol/server-github"
      ],
      "env": {
        "GITHUB_TOKEN": "ghp_secret"
      }
    },
    "gsc": {
      "command": "uvx",
      "args": [
        "mcp-search-console"
      ],
      "env": {
        "GSC_CREDENTIALS_PATH": "/root/.config/gsc/creds.json"
      }
    },
    "local": {
      "command": "local-mcp",
      "args": [
        "--root=/root/code"
      ]
    }
  },
  "projects": {
    "/Users/dev": {
      "allowedTools": [
        "Bash"
      ],
      "mcpServers": {
      }
    },
    "/root": {
      "mcpServers": {
        "zomato": {
          "type": "stdio",
          "command": "npx",
          "args": [
            "mcp-remote",
            "https://mcp.zomato.com/mcp"
          ]
        },
        "whatsapp": {
          "command": "uv",
          "args": [
            "--directory",
            "/root/code/wa",
            "run",
            "main.py"
          ]
        }
      }
    }
  }
}
